  ('heidschi', 'Heidschi', 'das', '', '', 'Grundwortschatz Wienerisch', 'Heidschi', '[{"kategorie": "wörtlich", "text": "\"Heidschi\" (lautmalerisches Wort, das den sanften, wiegenden Rhythmus eines Wiegenlieds nachahmt)"}, {"kategorie": "", "text": "\"Schlaf, Kindlein schlaf!\" (\"Heidschi\"=Verniedlichung bzw. Verballhornung von à„Heija“ oder „heija machen“ = schlafen gehen)"}, {"kategorie": "", "text": "Schlaf ein, mein Kind, schlaf ein! (analog zum Wiegenlied [[Heidschi Bumbeidschi]] [18. Jahrhundert] ist \"Heidschi\" ein Kosewort, mit dem Kinder in den Schlafgesungen werden)"}]'::jsonb, 'heidschi mochn'),
  ('heija', 'Heija', 'die', '', '', 'Echt wienerisch – so sagt man das in Wien!', 'Heija', '[{"kategorie": "wörtlich, Kindersprache", "text": "\"Heija\" (lautmalerisches Wort, das die weichen, beruhigenden Laute nachahmt, welche Erwachsene beim Wiegen oder Trösten von Kleinkindern verwenden)"}, {"kategorie": "allg.", "text": "Bettchen, Wiege, Bett, Schlafstatt"}]'::jsonb, 'Ob ind Heija!'),
  ('heidi', 'Heidi', 'das', '', '', 'Wiener Sprüche, die sitzen!', 'Heidi', '[{"kategorie": "wörtlich", "text": "\"Heidi\" (lautmalerisches Wort, das den sanften, wiegenden Rhythmus eines Wiegenlieds nachahmt)"}, {"kategorie": "", "text": "\"Schlaf, Kindlein schlaf!\" (\"Heidi\"=Verniedlichung bzw. Verballhornung von à„Heija“ oder „heija machen“ = schlafen gehen)"}, {"kategorie": "", "text": "Schlaf ein, mein Kind, schlaf ein! (analog zum Wiegenlied [[Heidschi Bumbeidschi]] [18. Jahrhundert] ist \"Heidi\" ein Kosewort, mit dem Kinder in den Schlafgesungen werden)"}]'::jsonb, 'Heidi mochn'),
  ('bubu', 'Bubu', 'das', '', '', 'Wiener Sprüche, die sitzen!', 'Bubu', '[{"kategorie": "wörtlich, Kindersprache", "text": "\"Bubu\" (lautmalerisches Wort, das den sanften, wiegenden Rhythmus eines Wiegenlieds nachahmt)"}, {"kategorie": "", "text": "\"Schlaf, Kindlein schlaf!\" (\"Bubu\"=Kosewort, mit dem Kinder in den Schlafgesungen werden [Verniedlichung bzw. Verballhornung des Titels des Wiegenlieds [[Heidschi Bumbeidschi]]])"}, {"kategorie": "", "text": "Schlaf ein, mein Kind, schlaf ein!"}]'::jsonb, 'Bubu mochn'),
  ('heidschibum', 'Heidschibum', 'das', '', '', 'Wiener Sprüche, die sitzen!', 'Heidschibum', '[{"kategorie": "wörtlich, Kindersprache", "text": "\"Heidschibum\" (lautmalerisches Wort, das den sanften, wiegenden Rhythmus eines Wiegenlieds nachahmt)"}, {"kategorie": "", "text": "\"Schlaf, Kindlein schlaf!\" (\"Heidschibum\"=Kosewort, mit dem Kinder in den Schlafgesungen werden [Verniedlichung bzw. Verballhornung des Titels des Wiegenlieds [[Heidschi Bumbeidschi]]])"}, {"kategorie": "", "text": "Schlaf ein, mein Kindchen, schlaf ein!"}]'::jsonb, 'Heidschibum mochn'),
  ('hendl', 'Hendl', 'das', '', '', 'Viecher und Tiernamen auf Wienerisch', 'Hendl', '[{"kategorie": "wörtlich", "text": "\"Hendl\" (Verkleinerungsform von [[Henn]], vom mittelhochdeutschen \"henne\"=\"Henne\")"}, {"kategorie": "allg.", "text": "Huhn, Haushuhn, Hähnchen"}]'::jsonb, 'Ob bochn oda broodn, a Hendl is mei Leibschbeis!'),
  ('hendlgottsocka', 'Hendlgottsocka', 'der', '', '', 'Echte Wiener Schmähperlen', 'Hendlgottsacker', '[{"kategorie": "wörtlich", "text": "\"Hühnerfriedhof\" (Determinativkompositum aus \"Hendl\"=\"Huhn\" und \"Gottsacker\"=\"Friedhof\")"}, {"kategorie": "scherzhaft für", "text": "\"Hähnchenfriedhof\", \"Backhendlwampe\", \"Fettbauch\", [[Waumpn]]"}]'::jsonb, 'Mit dem sein Hendlgottsocka kummda kaan Beag mea auffe - do geed nua no sitzn und saufn!'),
  ('heanpueuez', 'Heanpüüz', 'der', '', '', 'Botanik und Pflanzen auf Wienerisch', 'Herrenpilz', '[{"kategorie": "wörtlich", "text": "\"Pilz für die Herren\" (also für vornehme Leute, Adlige oder die Oberschicht - der Herrenpilz galt früher als besonders delikat, nahrhaft und kostbar, und wurde daher besonders geschätzt von den „feinen Herrschaften“ der Geswellschaft)"}, {"kategorie": "bot.", "text": "Steinpilz, (lateinischer Name): \"Boletus edulis\" (\"essbarer Röhrenpilz\" - Pilz aus der Ordnung der Röhrenpilze), Fichtensteinpilz, Edelpilz"}]'::jsonb, 'In da ghoobanan Kuchl wiad da Heanpüüz weng sein festn Fleisch gschätzd!'),
  ('hetschal', 'Hetschal', 'das', '', '', 'Botanik und Pflanzen auf Wienerisch', 'Hetscherl', '[{"kategorie": "wörtlich", "text": "\"Hetscherl\" (Verkleinerungsform von \"Hetsche\", vom mittelhochdeutschen \"hetsche\"=\"Frucht der Heckenrose\")"}, {"kategorie": "bot.", "text": "\"Hagebutte\", \"rote bis orangefarbene Frucht der Heckenrose\", (lateinische Bezeichnung): \"Rosa canina\" (Frucht der Hundsrose)"}]'::jsonb, 'Ois Buama hauma Hetschaln gsaummäd, aufbrochn und uns gegnseitig ois Juckpuiva untas Leiwal gschdraad!'),
  ('hetschaltee', 'Hetschaltee', 'der', '', '', 'Wiener Kaffeehaus-ABC', 'Hetscherltee', '[{"kategorie": "wörtlich", "text": "\"Hagebuttentee\" (Determinativkompositum aus \"Hetscherl\"=\"Hagebutte\" und \"Tee\"=\"Aufgussgetränk\")"}, {"kategorie": "allg.", "text": "\"Früchtetee mit Hagebutte\", \"Tee aus der roten bis orangefarbenen Frucht der Hundsrose\" (\"Rosa canina\"), \"Wildrosenfruchttee\""}]'::jsonb, 'I trink mein Hetschaltee imma mid an Leffä Hoonig - des beste Hausmittl gegn Frestln im Winta!'),
  ('hetschaln', 'hetschaln', '', '', '', 'Grundwortschatz Wienerisch', 'hätscherln', '[{"kategorie": "wörtlich", "text": "\"hätscheln\" (lautmalerisches Wort, das eine weiche, zärtliche Lautfolge imitiert [\"hätsch\"], welche oft mit kleinen Kindern oder liebevoller Zuwendung assoziiert wird)"}, {"kategorie": "allg.", "text": "jemanden verwöhnen, verhätscheln, liebkosen"}]'::jsonb, 'Mei Oide hetschald in Hund mea ois mi!'),
  ('hetz', 'Hetz', 'die', '', '', 'Grundwortschatz Wienerisch', 'Hetz', '[{"kategorie": "wörtlich", "text": "\"Hetz\" (vom mittelhochdeutschen \"heʒʒe\"=\"Hetze\")"}, {"kategorie": "hist.", "text": "Hatz, Tierhatz, Tierhetze (in Wien gab es im 18. Jahrhundert eine bekannte Tierkampfarena, die [[Hetztheater]] genannt wurde. Diese Arena befand sich in der Nähe des heutigen [[Hetzgassenviertels]] im 3. Wiener Gemeindebezirk. Dort wurden Tierhetzen veranstaltet, also Schaukämpfe mit Bären, Hunden, Stieren usw., die vom Publikum als „Unterhaltung“ betrachtet wurden. Obwohl diese Tierhetzen grausam waren, galten sie damals als Volksbelustigung – ein Spektakel, das die Leute amüsierte)"}, {"kategorie": "fig.", "text": "\"lustiges Treiben\", Spaß, Vergnügen,  [[Jux]], [[Terz]], [[Gaudee]] (mit der Zeit wandelte sich die Bedeutung von „Hetz“ = \"Tierhetze, aufregende Jagdveranstaltung\"  zu „Hetz“ = \"lustiges Treiben, Gaudi, Spaß\". Der grausame Hintergrund geriet zunehmend in Vergessenheit – die emotionale Komponente (Aufregung, Spannung, „Action“) blieb, aber wurde ins Positive umgedeutet)"}]'::jsonb, 'A Hetz muass sei!'),
  ('hetztaeata', 'Hetztäata', 'das', '', '', 'Wiener Wörter mit schillernder Geschichte', 'Hetztheater', '[{"kategorie": "wörtlich", "text": "\"Hetztheater\" (Determinativkompositum aus \"Hetz\"=\"Tierhetze\" und \"Theater\"=\"Arena\")"}, {"kategorie": "hist.", "text": "\"Tierkampfarena\" (in der Tierhetzen – also Kämpfe zwischen Tieren wie Bären, Hunden, Stieren oder Raubkatzen, aber auch zwischen Tier und Mensch – vor zahlendem Publikum veranstaltet wurden. Diese Arena befand sich in der Nähe des heutigen [[Hetzgassenviertels]] im 3. Wiener Gemeindebezirk, wurde 1755 eröffnet, hatte ein Fassungsvermögen von 3.000 Zuschauern und war ein beliebter Unterhaltungsschauplatz der Wiener Bevölkerung. Es war halb Theater, halb Arena – eine Mischung aus Spektakel, Gewalt und „Volksbelustigung“. Am 1. September 1796 wurde das Hetztheater durch ein Feuer zerstört und nicht wieder aufgebaut. Danach wurden Tierhetzen in Wien verboten – das entsprach auch dem sich wandelnden Zeitgeist, der solche Veranstaltungen zunehmend als grausam empfand. Die à„Hetzgasse“ in Wien erinnert bis heute an diese Arena. Und das Wort à„Hetz“ lebt im Wienerischen weiter – heute aber im harmlosen Sinne von „Spaß“ oder „Gaudi“, ohne Bezug zur ursprünglichen Grausamkeit)"}]'::jsonb, ''),
  ('hetzgossn', 'Hetzgossn', 'die', '', '', 'Wiener Gassen, Straßen & Plätze', 'Hetzgasse', '[{"kategorie": "wörtlich", "text": "\"Hetzgasse\" (Straße im 3. Wiener Gemeindebezirk [[[Landstraße]]], die ihren Namen zur Erinnerung an das ehemalige [[Wiener]] Hetztheater trägt, das sich in dieser Gegend befand)"}, {"kategorie": "hist.", "text": "Im [[Hetzgassenviertel]] befand sich im 18. Jahrhundert das berühmte \"Wiener Hetztheater\" - eine \"Tierkampfarena\", in der Tierhetzen – also Kämpfe zwischen Tieren wie Bären, Hunden, Stieren oder Raubkatzen, aber auch zwischen Tier und Mensch – vor zahlendem Publikum veranstaltet wurden. Es wurde 1755 eröffnet, hatte ein Fassungsvermögen von 3.000 Zuschauern und war ein beliebter Unterhaltungsschauplatz der Wiener Bevölkerung. Es war halb Theater, halb Arena – eine Mischung aus Spektakel, Gewalt und „Volksbelustigung“. Am 1. September 1796 wurde das Hetztheater durch ein Feuer zerstört und nicht wieder aufgebaut. Danach wurden Tierhetzen in Wien verboten – das entsprach auch dem sich wandelnden Zeitgeist, der solche Veranstaltungen zunehmend als grausam empfand. Die „Hetzgasse“ in Wien erinnert bis heute an diese Arena. Und das Wort à„Hetz“ lebt im Wienerischen weiter – heute aber im harmlosen Sinne von „Spaß“ oder „Gaudi“, ohne Bezug zur ursprünglichen Grausamkeit)"}, {"kategorie": "", "text": "Die Hetzgasse ist heute eine ruhige Wohnstraße mit klassischer Wiener Architektur, teilweise mit gründerzeitlichen Bauten. Sie liegt in einem Viertel, das heute auch wegen seiner Nähe zum Donaukanal, zur Innenstadt und zum [[Rochusmarkt]] als urban und beliebt gilt"}]'::jsonb, ''),
  ('hetzgossnviatl', 'Hetzgossnviatl', 'das', '', '', 'Wiener Gassen, Straßen & Plätze', 'Hetzgassenviertel', '[{"kategorie": "wörtlich", "text": "\"Das Stadtviertel um die [[Hetzgasse]]\" (lokale Bezeichnung für ein Stadtviertel im 3. Wiener Gemeindebezirk [[[Landstraße]]], benannt nach der [[Hetzgasse]], die das Viertel durchzieht)"}, {"kategorie": "hist.", "text": "Im Hetzgassenviertel befand sich im 18. Jahrhundert das berühmte \"Wiener Hetztheater\" - eine \"Tierkampfarena\", in der Tierhetzen – also Kämpfe zwischen Tieren wie Bären, Hunden, Stieren oder Raubkatzen, aber auch zwischen Tier und Mensch – vor zahlendem Publikum veranstaltet wurden. Es wurde 1755 eröffnet, hatte ein Fassungsvermögen von 3.000 Zuschauern und war ein beliebter Unterhaltungsschauplatz der Wiener Bevölkerung. Es war halb Theater, halb Arena – eine Mischung aus Spektakel, Gewalt und „Volksbelustigung“. Am 1. September 1796 wurde das Hetztheater durch ein Feuer zerstört und nicht wieder aufgebaut. Danach wurden Tierhetzen in Wien verboten – das entsprach auch dem sich wandelnden Zeitgeist, der solche Veranstaltungen zunehmend als grausam empfand. Die „Hetzgasse“ in Wien erinnert bis heute an diese Arena. Und das Wort à„Hetz“ lebt im Wienerischen weiter – heute aber im harmlosen Sinne von „Spaß“ oder „Gaudi“, ohne Bezug zur ursprünglichen Grausamkeit)"}, {"kategorie": "", "text": "Das Hetzgassenviertel ist heute eine ruhige Wohngegend mit klassischer Wiener Architektur, teilweise mit gründerzeitlichen Bauten. Sie liegt in einem Viertel, das heute auch wegen seiner Nähe zum [[Donaukanal]], zur Innenstadt und zum [[Rochusmarkt]] als urban und beliebt gilt"}]'::jsonb, ''),
  ('muadshetz', 'Muadshetz', 'die', '', '', 'Grundwortschatz Wienerisch', 'Mordshetz', '[{"kategorie": "wörtlich", "text": "\"mordsmäßig große Hetz\" (Determinativkompositum aus dem Präfixoid [[Mords-]]=\"mordsmäßig groß\" und \"Hetz\"=\"Spaß\", in Anspielung auf das einst berühmte [[Hetztheater]] in Wien, in dem seinerzeit Tierhetzen veranstaltet wurden, die damals als allgemeine Volksbelustigung galten)"}, {"kategorie": "allg.", "text": "Riesenspaß, Mordsvergnügen, Riesengaudi, \"Spaß ohne Ende\", [[Mordsgaudi]], [[Mordsjux]], [[Mordskarl]], [[Mordstheater]]"}]'::jsonb, 'Oida, da Kiatoog gestan woara Muadshetz - do haums gsoffn, grööd und si aum Schluss aa no ind Goschn ghaud!'),
  ('hetzhoiwa', 'hetzhoiwa', '', '', '', 'Wiener Sprüche, die sitzen!', 'hetzhalber', '[{"kategorie": "wörtlich", "text": "\"um der Hetz willen\" (Kompositum aus \"Hetz\"=\"Spaß\" und \"halber\"=\"um…willen\", in Anspielung auf das einst berühmte [[Hetztheater]] in Wien, in dem seinerzeit Tierhetzen veranstaltet wurden, die damals als allgemeine Volksbelustigung galten)"}, {"kategorie": "allg.", "text": "\"spaßhalber\", aus Spaß, zur Belustigung, einfach nur zum Vergnügen, aus [[Jux]], [[aus]] Jux und Tollerei, [[zwecks]] Gaudee, [[zwecks]] Theater"}]'::jsonb, 'Hetzhoiwa hob I domois a Beweabung gschickd - und jetzt bin Obtäulungsleita!'),
  ('botznhetz', 'Botznhetz', 'die', '', '', 'Grundwortschatz Wienerisch', 'Batzenhetz', '[{"kategorie": "wörtlich", "text": "\"Batzenhetz\" (Determinativkompositum aus dem Präfixoid \"Batzen\"=\"gewaltig groß\" und [[Hetz]]=\"Spaß\", in Anspielung auf das einst berühmte [[Hetztheater]] in Wien, in dem seinerzeit Tierhetzen veranstaltet wurden, die damals als allgemeine Volksbelustigung galten)"}, {"kategorie": "allg.", "text": "Riesenspaß, Riesengaudi, [[Mordsgaudi]]!"}]'::jsonb, 'Moch ma uns a Botznhetz!'),
  ('heia', 'heia', '', '', '', 'Grundwortschatz Wienerisch', 'heuer', '[{"kategorie": "wörtlich", "text": "\"heuer\" (vom mittelhochdeutschen \"hiure\"=\"in diesem Jahre\")"}, {"kategorie": "allg.", "text": "diesjährig, dieses Jahr, im aktuellen Jahr"}]'::jsonb, 'heia gee'),
  ('heiriche', 'Heiriche', 'die', '', '', 'Botanik und Pflanzen auf Wienerisch', 'Heurige', '[{"kategorie": "wörtlich, Pluralform", "text": "\"Heurige\" (vom mittelhochdeutschen \"hiure\"=\"diesjährig\")"}, {"kategorie": "bot.", "text": "\"Frühkartoffeln\", \"Jungerdäpfel\", \"die Diesjährigen\", \"Erdäpfel (Kartoffeln) aus der diesjährigen Ernte\""}]'::jsonb, 'De Heirichn ausn Moachfööd  schmeckn bsundas zoat und lossn si aa leicht schöön!'),
  ('heiricha', 'Heiricha', 'der', '', '', 'Grundwortschatz Wienerisch', 'Heuriger', '[{"kategorie": "allg.", "text": "\"traditionelle Wiener Weinschenke, in der vor allem der „Heurige“ (also der junge, in der aktuellen Saison produzierte) Wein ausgeschenkt wird\""}, {"kategorie": "Definition", "text": "\"Ausschankbetrieb für den eigenen Wein des aktuellen Jahrgangs (= „heuriger Wein“), sowie für hausgemachte kalte und warme Speisen\" (die Bezeichnung „Heuriger“ leitet sich vom Wort „heuer“ ab, was im Wienerischen „dieses Jahr“ bedeutet. Ein Heuriger ist somit ursprünglich ein Lokal, in dem der Winzer seinen neu produzierten Wein des laufenden Jahres direkt an Gäste verkauft und ausschenkt)"}, {"kategorie": "allg.", "text": "Weinlokal, Weinschenke, Weinausschank (wo vorwiegend \"der Heurige\" aus Eigenbau, meist nur während bestimmter Öffnungszeiten, ausgeschenkt wird)"}, {"kategorie": "Winzerjargon", "text": "\"Wein des jüngsten Jahrganges\", \"Jungwein\" (im Gegensatz zum [[Oidn]] = Altwein)"}, {"kategorie": "jur.", "text": "Der Begriff „Heuriger“ ist auch rechtlich geschützt. Nur Lokale, die den aktuellen Jahrgang ausschenken, dürfen sich so nennen. Oftmals wird dies durch die vor dem Lokal ausgehängten Reisigzweige angezeigt, welche signalisieren, dass der Heurige geöffnet ist"}, {"kategorie": "Zusammenfassung", "text": "Der Begriff „Heuriger“ bezeichnet somit sowohl den Wein des aktuellen Jahrgangs als auch das Lokal selbst"}]'::jsonb, ''),
  ('buschnschaunk', 'Buschnschaunk', 'die', '', '', 'Grundwortschatz Wienerisch', 'Buschenschank', '[{"kategorie": "wörtlich", "text": "\"Heurigenausschank, vor welcher ein Reisigbuschen hängt\" (als Zeichen dafür, dass das Lokal geöffnet ist - Determinativkompositum aus [[Buschen]]=\"Reisigbusch\" und [[Schank]]=\"Schenke\")"}, {"kategorie": "", "text": "Heurigenschenke, \"Hofschank\" (zeitweiliger Ausschank ortsüblicher Getränke wie Jung- und Altwein, aber auch Most, seltener Bier und Schnaps)"}, {"kategorie": "", "text": "Definition: \"bäuerlicher Betrieb, der nur eigene Produkte (Wein, Most, Jause) ausschenken darf – kein Bier, keine warmen Speisen, kein zugekauftes Zeug (der Name \"Buschenschank\" leitet sich von der Sitte ab, dass ein Zweig oder ein „Buschen“ [meist aus Föhrenzweigen oder Reisig] vor dem Eingang des Lokals aufgehängt wird, um anzuzeigen, dass die Buschenschank geöffnet ist)"}, {"kategorie": "", "text": "In Österreich ist der Betrieb einer Buschenschank rechtlich geregelt. Winzer dürfen ihre Buschenschank nur für eine begrenzte Anzahl von Tagen im Jahr öffnen, um ihre eigenen Produkte anzubieten. Dies unterscheidet die Buschenschank vom dauerhaften Betrieb eines Gasthauses"}]'::jsonb, 'In da Buschnschaunk kriagst an gscheidn Schbeck und an eiganan Vöötlina - beim Heirichn sogoa a Schnitzl und a Puntigama!'),
  ('buschn', 'Buschn', 'der', '', '', 'Grundwortschatz Wienerisch', 'Buschen', '[{"kategorie": "wörtlich", "text": "\"Buschen\" (vom mittelhochdeutschen \"busch\"=\"Büschel\")"}, {"kategorie": "allg., kurz für", "text": "\"Reisigbusch\" (bezieht sich auf die ursprüngliche Praxis, vor dem Weinlokal einen Reisigbusch aufzuhängen, um so anzuzeigen, dass im Lokal aktuell ausgeschenkt wird"}, {"kategorie": "scherzhaft für", "text": "starke Schambehaarung, stark behaartes weibliches Geschlechtsteil, [[Brunzbuschn]]"}]'::jsonb, 'Waunn a Buschn vuam Eigaung hängd, waass a jeeda, dass ausgschdeckd is und ausgeschenkd wiad!'),
  ('hiib', 'Hiib', 'der', '', '', 'Grundwortschatz Wienerisch', 'Hieb', '[{"kategorie": "wörtlich", "text": "\"Hieb\" (vom mittelhochdeutschen \"hieben\"=\"schlagen mit einer Waffe oder einem Werkzeug“)"}, {"kategorie": "allg.", "text": "kräftiger Schlag, Stoß, Boxhieb"}, {"kategorie": "scherzhaft für", "text": "Dachschaden, [[Pecker]], [[G]]+C3818laumsch"}, {"kategorie": "Winzerjargon", "text": "\"Weingarten auf einer gerodeten Fläche\", \"neu bestockter Weinschlag\", \"Rebfläche auf ehemaliger Waldfläche\""}, {"kategorie": "bezogen auf Wien", "text": "Bezirk, Stadtbezirk, Wiener Gemeindebezirk (in Anspielung darauf, dass - anlässlich der neuen Stadtaufteilung Wiens im Jahr  1862 - mit \"jedem Hieb\" neue Bezirke wie Stücke aus einer Torte gehauen wurden)"}]'::jsonb, 'Mit an aanzign Hiib aufs Kinn hoda in Geegna K.O. gschloong!'),
  ('simmaring', 'Simmaring', '', '', '', 'Wiener Prachtpalais und Prunkbauten', 'Simmering', '[{"kategorie": "wörtlich", "text": "\"Wien-Simmering\""}, {"kategorie": "", "text": "\"der elfte [[Hieb]]\" (= 11. Wiener Gemeindebezirk)"}, {"kategorie": "", "text": "Simmering liegt im Südosten der Stadt Wien und ist bekannt für seine industrielle Vergangenheit, seine multikulturelle Bevölkerung und seine Mischung aus urbanem Leben und weitläufigen Grünflächen. Simmering hat eine reiche Geschichte und spielt eine wichtige Rolle in der städtischen Infrastruktur Wiens"}, {"kategorie": "", "text": "Simmering wurde 1892 gemeinsam mit den damaligen Vororten [[Kaiserebersdorf]], [[Albern]] und anderen nach Wien eingemeindet. Ursprünglich war der Bezirk stark landwirtschaftlich geprägt, entwickelte sich aber im Laufe der Industrialisierung zu einem wichtigen Industrie- und Gewerbestandort. Der Bezirk war lange Zeit bekannt für seine Gaswerke (siehe [[Gaswerk Simmering]] und [[Gasometer]]), die die Stadt mit Stadtgas versorgten, sowie für andere industrielle Betriebe wie die [[Simmeringer]] Waggonfabrik"}, {"kategorie": "", "text": "Simmering war traditionell ein Zentrum der Industrie und des Handwerks in Wien. Die Industriebetriebe spielten eine zentrale Rolle in der Entwicklung des Bezirks, und auch heute noch gibt es viele Gewerbe- und Industrieflächen in Simmering. Der Bezirk beherbergt wichtige Infrastrukturprojekte wie das [[Wiener]] Gaswerk, die [[Wiener]] Hauptkläranlage und den [[Zentralfriedhof]], der einer der größten Friedhöfe Europas ist"}, {"kategorie": "", "text": "Die bekanntesten [[Grätzln]] des Bezirks sind [[Alt-Simmering]] (historischer Kern mit Pfarrkirche), [[Kaiserebersdorf]] (Vorstadt mit Einfamilienhäusern), [[Neu-Simmering]] ([[Gemeindebauten]] und moderne Wohnsiedlungen), [[Gasometer]] City (junges Wohn- und Eventviertel) und der [[Leberberg]] (Neubaugebiet mit großem Wohnungsbau)"}, {"kategorie": "", "text": "Simmering ist ein traditionsreicher, bodenständiger Wiener Bezirk mit starkem Wandelpotenzial. Von Industrie und Arbeiterkultur geprägt, entwickelt er sich heute zu einem vielfältigen Wohn- und Entwicklungsgebiet mit kulturellen Highlights wie den Gasometern und dem Zentralfriedhof. Simmering bietet viel Wohnraum, Geschichte und Lebensrealität – jenseits des innerstädtischen Wiens."}]'::jsonb, ''),
  ('gasometa', 'Gasometa', '', '', '', 'Wiener Denkmäler & steinerne Zeitzeugen', 'Gasometer', '[{"kategorie": "allg.", "text": "vier markante, denkmalgeschützte ehemalige Gasbehälter, die im 11. Wiener Gemeindebezirk ([[Simmering]]) stehen"}, {"kategorie": "", "text": "Die Gasometer wurden zwischen 1896 und 1899 errichtet, um das in den nahegelegenen Wiener Gaswerken erzeugte Stadtgas zu speichern. Sie waren Teil der städtischen Gasversorgung und konnten jeweils bis zu 90.000 Kubikmeter Gas fassen. Mit der Umstellung von Stadtgas auf Erdgas in den 1970er Jahren verloren die Gasometer ihre ursprüngliche Funktion und wurden 1984 stillgelegt"}, {"kategorie": "", "text": "Nach ihrer Stilllegung als Gasbehälter wurden die Gasometer Ende der 1990er Jahre umfassend renoviert und in ein modernes Wohn-, Geschäfts- und Kulturzentrum umgewandelt"}, {"kategorie": "", "text": "Die vier Gasometer sind massive Ziegelbauten im Industriearchitekturstil des ausgehenden 19. Jahrhunderts. Jeder der Zylinder hat einen Durchmesser von etwa 60 Metern und eine Höhe von rund 70 Metern. Die Fassade der Gasometer ist geprägt von Ziegelmauerwerk mit dekorativen Elementen, was ihnen ein imposantes und markantes Erscheinungsbild verleiht."}]'::jsonb, ''),
  ('enkplotz', 'Enkplotz', '', '', '', 'Wiener Gassen, Straßen & Plätze', 'Enkplatz', '[{"kategorie": "allg.", "text": "zentraler Platz im historischen Zentrum des 11. Wiener Gemeindebezirks ([[Simmering]])"}, {"kategorie": "", "text": "Rund um den Enkplatz befinden sich zahlreiche öffentliche Einrichtungen, darunter das Bezirksamt für den 11. Bezirk (Simmering), mehrere Schulen und die [[Pfarrkirche]] St. Laurenz, eine der ältesten Kirchen in Simmering"}, {"kategorie": "", "text": "Der Enkplatz ist nach Johann Enk von der Burg, einem früheren Bürgermeister von Wien, benannt, der sich im 19. Jahrhundert um die Entwicklung des Bezirks Simmering verdient gemacht hat"}, {"kategorie": "", "text": "Der Enkplatz ist ein wichtiges Zentrum des Bezirkslebens und wird regelmäßig für lokale Veranstaltungen, Märkte und andere öffentliche Aktivitäten genutzt."}]'::jsonb, ''),
  ('laurenzkiachn', 'Laurenzkiachn', '', '', '', 'Wiener Kirchen & Gotteshäuser', 'Laurenzkirche', '[{"kategorie": "allg., Kurzform für", "text": "\"Pfarrkirche Sankt Laurenz\" - bedeutende katholische Kirche im 11. Wiener Gemeindebezirk ([[Simmering]]) und eine der ältesten Kirchen Wiens"}, {"kategorie": "", "text": "Sie wurde erstmals im 11. Jahrhundert urkundlich erwähnt, wobei der genaue Zeitpunkt der Errichtung unklar ist"}, {"kategorie": "", "text": "Die Kirche ist nach dem heiligen Laurentius benannt und wird daher auch als [[Laurenzkirche]] bezeichnet"}, {"kategorie": "", "text": "Sie ist ein typisches Beispiel für eine gotische Kirche, obwohl sie Elemente verschiedener Epochen in ihrer Architektur vereint. Der Bau besteht aus einem gotischen Hauptschiff mit barocken und neugotischen Elementen, die im Laufe der Jahrhunderte hinzugefügt wurden"}, {"kategorie": "", "text": "Besonders markant ist der Kirchturm, der das Erscheinungsbild der Kirche prägt. Der Innenraum der Kirche ist schlicht, aber eindrucksvoll, mit einem gotischen [[Kreuzrippengewölbe]] und barocken Altären. Besonders erwähnenswert ist der Hauptaltar, der im barocken Stil gestaltet ist und das Martyrium des heiligen Laurentius darstellt"}, {"kategorie": "", "text": "Im Inneren der Kirche finden sich auch Grabmäler und Gedenktafeln, die an bedeutende Persönlichkeiten und Familien der Region erinnern."}]'::jsonb, ''),
  ('hiafla', 'Hiafla', 'der', '', '', 'Grundwortschatz Wienerisch', 'Hiefler', '[{"kategorie": "wörtlich eigentlich", "text": "\"Hüfler\" (vom mittelhochdeutschen \"hiufel\"=\"schwerfälliges Huftier\")"}, {"kategorie": "scherzhaft für", "text": "\"Blindgänger\", Tölpel, Versager, Dumpfbacke, [[Wappla]], [[Wää]], [[Schluffi]], [[Doim]],  [[Dillo]], [[bootschada]] Zwüüling"}]'::jsonb, 'Waunn ma den wos mochn lossd, geed garantiad wos schiif - a totala Hiafla hoid!'),
  ('hiabla', 'Hiabla', 'der', '', '', 'Grundwortschatz Wienerisch', 'Hiebler', '[{"kategorie": "wörtlich", "text": "\"Mensch mit einem Dachschaden\" (also jemand, der \"einen [[Hieb]] abgekriegt hat\", vom mittelhochdeutschen \"hieben\"=\"schlagen mit einer Waffe oder einem Werkzeug“)"}, {"kategorie": "scherzhaft für", "text": "Schwachkopf, Hohlbirne, Blindgänger, Tölpel, [[Doim]], Dillo, [[Wää]], [[Wappla]], [[Hianschissla]], [[Hianeedal]], [[Hiani]], [[Psychal]]"}]'::jsonb, 'Loss den Hiabla nix allaanich montian - dea schraubda sunst de Tiaklinkn aum Plafoo!'),
  ('hiinnich', 'hiinnich', '', '', '', 'Grundwortschatz Wienerisch', 'hinnig', '[{"kategorie": "wörtlich", "text": "\"kaputt\" (vom mittelhochdeutschen \"hinnic\"=\"lahm\" bzw. \"hinkend\")"}, {"kategorie": "Obst, Gemüse", "text": "verdorben, verfault, faulig (à\"De Paradeisa san hiinnich - de kaunnst olle wegschmeissn!)"}, {"kategorie": "allg.", "text": "kaputt, defekt, nicht mehr zu gebrauchen"}, {"kategorie": "", "text": "leblos, tot, verstorben, \"hinüber\""}, {"kategorie": "", "text": "schwerkrank, halbtot, \"körperlich am Ende\""}, {"kategorie": "fig.", "text": "\"geistig kaputt\", bescheuert, \"nicht ganz dicht\", strohdumm, [[saudeppert]]"}]'::jsonb, 'De Paradeisa san hiinnich - de kaunnst olle wegschmeissn!'),
  ('hii', 'hii', '', '', '', 'Grundwortschatz Wienerisch', 'hin', '[{"kategorie": "wörtlich", "text": "\"kaputt\" (vom mittelhochdeutschen \"hinnic\"=\"lahm\" bzw. \"hinkend\")"}, {"kategorie": "Obst, Gemüse", "text": "verdorben, verfault, faulig, [[hiinich]] (à\"De Paradeisa san hii - de kaunnst olle wegschmeissn!)"}, {"kategorie": "allg.", "text": "kaputt, defekt, nicht mehr zu gebrauchen, [[hiinich]]"}, {"kategorie": "", "text": "leblos, tot, verstorben, \"hinüber\", [[hiinich]]"}, {"kategorie": "", "text": "schwerkrank, halbtot, \"körperlich am Ende\", [[hiinich]]"}, {"kategorie": "fig.", "text": "\"geistig kaputt\", bescheuert, \"nicht ganz dicht\", strohdumm, [[saudeppert]], [[hiinnich]]"}]'::jsonb, 'De Paradeisa san hii - de kaunnst olle wegschmeissn!'),
  ('hiinnicha', 'Hiinnicha', 'der', '', '', 'Krank & kuriert auf Wienerisch', 'Hinnicher', '[{"kategorie": "wörtlich", "text": "\"Hinniger\" (vom mittelhochdeutschen \"hinnic\"=\"lahm\" bzw. \"hinkend\");  2.(med.) Schwerkranker, Halbtoter, Sterbenskranker"}, {"kategorie": "fig.", "text": "Geisteskranker, Vollidiot, [[Trottel]], [[Hirnschüssler]], [[Dillo]], [[Depp]], [[Schüttler]]"}]'::jsonb, 'Gestan woara no feian und heit schbüüda in Hiinnichn - klassische Montoogstaktik!'),
  ('himlitzn', 'himlitzn', '', '', '', 'Grundwortschatz Wienerisch', 'himlitzen', '[{"kategorie": "wörtlich", "text": "\"himmlitzen\" (vom mittelhochdeutschen \"himel-litzen\"=\"wetterleuchten\")"}, {"kategorie": "allg.", "text": "blitzen (am Himmel), funkeln, aufleuchten, wetterleuchten"}]'::jsonb, 'Waunns in aana Tua himlitzn tuad, ziagd a Weeda auf!'),
  ('hianeedal', 'Hianeedal', 'das', '', '', 'Echte Wiener Schmähperlen', 'Hirnederl', '[{"kategorie": "wörtlich", "text": "\"Hirnöderl\" (Verkleinerungsform von \"Hirnöder\", vom mittelhochdeutschen \"hirn-œde\"=\"hirnleer\")"}, {"kategorie": "allg.", "text": "\"Hirnloser\" (Mensch, in dessen Gehirn gähnende Leere herrscht), Schwachkopf, Dummkopf, Idiot, [[Trottel]], [[Hirnschüssler]], [[Doodl]], [[Dolm]], [[Psycherl]]"}]'::jsonb, 'Wia kau ma soo a Hianeedal sei und trotzdem an Füüraschein haum?'),
  ('holla', 'Holla', 'der', '', '', 'Grundwortschatz Wienerisch', 'Holler', '[{"kategorie": "wörtlich", "text": "\"Holler\" (vom mittelhochdeutschen \"holer\"=\"Holler\")"}, {"kategorie": "bot.", "text": "Holunder (Pflanzengattung aus der Familie der Moschuskrautgewächse), (lateinische Bezeichnung): \"Sambucus nigra\", [[schwarzer Holler]]"}, {"kategorie": "fig.", "text": "Quatsch, Unsinn, Blödsinn, [[Schduss]], [[Schmoan]]"}, {"kategorie": "", "text": "wertloses Zeug, Plunder, [[Klumpert]], [[Raumsch]], [[Krempä]], [[Tinnef]]"}]'::jsonb, 'Da Holla bliad im Mai - und daunn kumman de gaunzn Bio-Heinis und mochn an Sirup draus!'),
  ('hoppadaadschad', 'hoppadaadschad', '', '', '', 'Grundwortschatz Wienerisch', 'hoppertatschert', '[{"kategorie": "wörtlich", "text": "\"hoppertatschert\" (österreichische Volksschöpfung, zusammengesetzt aus den beiden lautmalerischen Bestandteilen \"hopper\"=\"umherhüpfend\" und \"tatschert\"=\"unbeholfen\")"}, {"kategorie": "allg.", "text": "tollpatschig, unbeholfen, ungeschickt, schwerfällig"}]'::jsonb, 'Schdöö di ned so hoppadaadschad au - a jeeda Depp schofft des!'),
  ('hoppadaadschich', 'hoppadaadschich', '', '', '', 'Grundwortschatz Wienerisch', 'hoppertatschig', '[{"kategorie": "allg.", "text": "tollpatschig, unbeholfen, ungeschickt, schwerfällig"}]'::jsonb, 'Heast Oida, schdöö di ned so hoppadaadschich au - a jeeda Depp schofft des!'),
  ('hoppadaadschada', 'Hoppadaadschada', 'der', '', '', 'Grundwortschatz Wienerisch', 'Hoppertatscherter', '[{"kategorie": "wörtlich", "text": "\"Hoppertatscherter\" (österreichische Volksschöpfung, zusammengesetzt aus den beiden lautmalerischen Bestandteilen \"hopper\"=\"umherhüpfend\" und \"tatschert\"=\"unbeholfen\")"}, {"kategorie": "allg.", "text": "Tollpatsch, ungeschickter Mensch, Schussel, [[Dillo]]"}]'::jsonb, 'Bei dem Hoppadaadschadn muassd Aungst haum, dassa iwad eiganen Fiass foid!'),
  ('hoppadaadschicha', 'Hoppadaadschicha', 'der', '', '', 'Grundwortschatz Wienerisch', 'Hoppertatschiger', '[{"kategorie": "wörtlich", "text": "\"Hoppertatschiger\" (österreichische Volksschöpfung, zusammengesetzt aus den beiden lautmalerischen Bestandteilen \"hopper\"=\"umherhüpfend\" und \"tatschig\"=\"unbeholfen\")"}, {"kategorie": "allg.", "text": "Tollpatsch, ungeschickter Mensch, Schussel, [[Dillo]]"}]'::jsonb, 'Glaub mas, bei dem Hoppadaadschichn muassd Aungst haum, dassa iwad eiganen Fiass foid!'),
  ('hoppala', 'Hoppala', 'das', '', '', 'Grundwortschatz Wienerisch', 'Hoppala', '[{"kategorie": "wörtlich", "text": "\"Hoppala\" (vom französischen \"Hop-là!\"=\"Hops!\")"}, {"kategorie": "allg.", "text": "\"kleiner Ausrutscher\", Mißgeschick, Malheur, Fauxpas"}, {"kategorie": "", "text": "Fahrbahnschwelle, Bodenschwelle, Bremshügel (zur Einbremsung der Schnellfahrer)"}, {"kategorie": "", "text": "Ausruf der Überraschung (bei einem Versehen, z.B. wenn jemand stolpert)"}]'::jsonb, 'So a Hoppala kaunn an jeedn moi passian!'),
  ('hoppla', 'Hoppla!', '', '', '', 'Wiener Sprüche, die sitzen!', 'Hoppla!', '[{"kategorie": "wörtlich", "text": "\"Hoppla!\" (Interjektion, vom französischen \"Hop-là!\"=\"Hops!\")"}, {"kategorie": "spontaner Ausruf als Reaktion auf ein kleines Missgeschick oder einen Schreck, z.B. wenn jemand stolpert, etwas herunterfällt oder überraschend etwas passiert", "text": "\"Oh!\", \"Ups!\", \"Na sowas!\""}, {"kategorie": "spontaner Ausruf als Kommentar zu einer unerwarteten Wendung, z. B. wenn jemand plötzlich etwas Unerwartetes sagt oder tut", "text": "\"Ach so!\", \"Na bitte!\", \"Aha!\""}, {"kategorie": "ironisch oder spöttisch, um Überraschung oder Empörung auszudrücken", "text": "\"Upsi!\", \"Autsch!\" \"Oje!\""}]'::jsonb, 'Hoppla, do hod si aana iwanumman!'),
  ('hoppsala', 'Hoppsala!', '', '', '', 'Wiener Sprüche, die sitzen!', 'Hoppsala!', '[{"kategorie": "wörtlich", "text": "\"Hoppsala!\" (Interjektion, vom französischen \"Hop-là!\"=\"Hops!\")"}, {"kategorie": "spontaner Ausruf als Reaktion auf ein kleines Missgeschick oder einen Schreck, z.B. wenn jemand stolpert, etwas herunterfällt oder überraschend etwas passiert", "text": "\"Oh!\", \"Ups!\", \"Na sowas!\""}, {"kategorie": "spontaner Ausruf als Kommentar zu einer unerwarteten Wendung, z. B. wenn jemand plötzlich etwas Unerwartetes sagt oder tut", "text": "\"Ach so!\", \"Na bitte!\", \"Aha!\""}, {"kategorie": "ironisch oder spöttisch, um Überraschung oder Empörung auszudrücken", "text": "\"Upsi!\", \"Autsch!\" \"Oje!\""}]'::jsonb, 'Hoppsala, do hod si aana iwanumman!'),
  ('hoeoeschaln', 'hööschaln', '', '', '', 'Grundwortschatz Wienerisch', 'höscherln', '[{"kategorie": "wörtlich", "text": "\"jemanden im Kreis laufen lassen\"+C3940"}, {"kategorie": "allg.", "text": "sich über jemanden lustig machen, jemanden auf den Arm nehmen, verspotten, verhöhnen, verarschen"}, {"kategorie": "Fußballerjargon", "text": "\"einen Spieler beim Training im Kreis laufen lassen\", \"die Fußball-Trainingseinheit ''Ball-im-Kreis-Jagen'' praktizieren\", \"die ''Schweinchen-in-der-Mitte Trainingseinheit'' vollziehen\" (im engen Kreis stehende Kicker spielen sich den Ball zu, den ein in ihrer Mitte Agierender erwischen muss)"}]'::jsonb, 'I loss mi ned gean hööschaln - meak da des aa fia olle Moi, Oida!'),
  ('ballestara', 'Ballestara', 'der', '', '', 'Wiener Fußballer- und Sportlerjargon', 'Ballesterer', '[{"kategorie": "wörtlich", "text": "\"Ballesterer\" (vom italienischen \"balestra\"=\"Wurfmaschine\" – das Wort \"Ballesterer\" geht etymologisch auf das italienische \"balestra\" [‚Armbrust‘ bzw. ‚Wurfmaschine‘] zurück. Aufgrund seiner lautlichen Nähe zum deutschen Lexem ‚Ball‘ wurde es im fußballsprachlichen Kontext reanalysiert und volksetymologisch angepasst, wodurch sich die eingedeutschte Schreibweise mit Doppel-‚l‘ etablierte)"}, {"kategorie": "Fußballerjargon", "text": "Fußballer, Fußballspieler, \"Freizeitspieler\", \"Vergnügungsfußballer\""}]'::jsonb, 'Ea is kaa Profi, owa a echta Ballestara - jeede Wochn schdeeda mid seine Haawara aum Plotz!'),
  ('ballestan', 'ballestan', '', '', '', 'Wiener Fußballer- und Sportlerjargon', 'ballestern', '[{"kategorie": "wörtlich", "text": "\"ballestern\" (vom italienischen \"balestra\"=\"Wurfmaschine\" – das Wort \"ballestern\" geht etymologisch auf das italienische \"balestra\" [‚Armbrust‘ bzw. ‚Wurfmaschine‘] zurück. Aufgrund seiner lautlichen Nähe zum deutschen Lexem ‚Ball‘ wurde es im fußballsprachlichen Kontext reanalysiert und volksetymologisch angepasst, wodurch sich die eingedeutschte Schreibweise mit Doppel-‚l‘ etablierte)"}, {"kategorie": "allg.", "text": "\"Fußball spielen\", \"als Freizeitkicker aktiv sein\", \"hobbymäßig Fußball spielen\", \"aus Spaß am Spiel kicken\""}]'::jsonb, 'Aum Sunndoog findst im Prooda kaa aanzige Wiesn, wo ned ballestad wiad!'),
  ('eisnbauna', 'Eisnbauna', 'der', '', '', 'Wiener Fußballer- und Sportlerjargon', 'Eisenbahner', '[{"kategorie": "wörtlich", "text": "\"plötzlicher, unerwartet harter Stoß von hinten ins Gesäß oder den Oberschenkel\" (Metapher: \"So wie eine Lok von hinten anschiebt, stößt auch das Knie kräftig ins Gesäß\")"}, {"kategorie": "allg.", "text": "\"Stoß mit dem Knie ins Gesäß\", \"Kniestoß in den Hintern\", \"kräftiger Kniestoß in den Oberschenkel\""}]'::jsonb, 'Bei uns in da U17 woas noamal - wea zspääd kumma is, hod vom Trääna an Eisenbauna kassiad!'),
  ('banaan', 'Banaan', 'die', '', '', 'Grundwortschatz Wienerisch', 'Banane', '[{"kategorie": "wörtlich", "text": "\"Banane\" (vom portugiesischen \"banana\", ursprünglich aus einer Bantusprache oder Mundart Guineas oder des Kongo)"}, {"kategorie": "bot.", "text": "Banane, (lateinischer Gattungsname): \"Musa\", Krummfrucht, Paradiesfeige"}, {"kategorie": "Fußballerjargon", "text": "\"Flanke mit viel tückischem Effet\" (meist mit dem Außenrist); \"Bogenlampe\" (wenn der Ball besonders hoch und gekrümmt fliegt), \"Bananenflanke\""}, {"kategorie": "scherzhaft für", "text": "Penis, Schniedl, [[Beidl]], [[Nuudl]], [[Familienschdrumpf]], [[Zumpfal]], [[Fruchtwuazn]]"}]'::jsonb, 'Banaanan wochsn auf Schdaudn, ghean owa zu den Beeanfrüchtn!'),
  ('ooschdaubagoi', 'Ooschdaubagoi', 'das', '', '', 'Wiener Fußballer- und Sportlerjargon', 'Abstaubergoal', '[{"kategorie": "wörtlich", "text": "\"Abstaubertor\" (Determinativkompositum aus \"Abstauber\"=\"Nachschuss\" und \"Goal\"=\"Tor\")"}, {"kategorie": "Fußballerjargon", "text": "\"Nachschusstor aus kürzester Distanz\" (Tor, bei dem der Spieler den Ball ohne viel Mühe und Eigenleistung nur noch ins Tor drücken muss), \"Nachstochertor\", \"klassischer Abstauber\""}]'::jsonb, 'Ea schdeed genau richtig und vasenkd in Ooprolla eiskoid - a klassisches Ooschdaubagoi!'),
  ('knipsa', 'Knipsa', 'der', '', '', 'Grundwortschatz Wienerisch', 'Knipser', '[{"kategorie": "wörtlich", "text": "\"Knipser\" (von \"knipsen\"=\"etwas mit einem kleinen, schnellen Druck auslösen, entfernen, durchtrennen, aktivieren etc.\", lautmalerisches Wort, das ein kurzes, knackendes oder schnappendes Geräusch nachhahmt)"}, {"kategorie": "allg.", "text": "Nagelknipser (Gerät zur Pflege der Fuß- und Fingernägel), Nagelschneider, Nagel-Clipper"}, {"kategorie": "scherzhaft für", "text": "Amateurfotograf, Hobbyfotograf, Freizeitfotograf"}, {"kategorie": "Fußballerjargon", "text": "Goalgetter, Torjäger (besonders erfolgreicher Torschütze), \"Super-Stürmer\""}]'::jsonb, 'So an Knipsa winschad si jeeda Trääna - eiskoid vuam Tiarl und imma zua Schdöö!'),
  ('schbitz', 'Schbitz', 'der', '', '', 'Grundwortschatz Wienerisch', 'Spitz', '[{"kategorie": "wörtlich", "text": "\"Spitz\" (vom mittelhochdeutschen \"spiz\"=\"Spitz\")"}, {"kategorie": "", "text": "\"Spitz\" (Hunderasse mit spitzer Schnauze und aufrecht stehenden, spitzen Ohren, mit geringeltem Schwanz und meist langhaarigem, schwarzem oder weißem Fell), Zwergspitz (Pomeranian), \"Flauschhund\", \"Kläffer\""}, {"kategorie": "Fleischhauerjargon", "text": "spitz zulaufendes Teilstück vom Rind"}, {"kategorie": "scherzhaft für", "text": "leichter Rausch, Schwips, [[Spitzerl]]"}, {"kategorie": "Fußballerjargon", "text": "unkontrollierter Pass oder Schuss mit der Schuhspitze, (Deutschland): unkontrollierter Pass oder Schuss mit der Pike"}, {"kategorie": "", "text": "Tritt mit der Schuhspitze ins Gesäß, \"Schuhpikser in den Hintern\", [[Lochspitz]]"}, {"kategorie": "scherzhaft für", "text": "Penis, Schwanz, [[Beidl]], [[Nuudl]], [[Guakal]], [[Familienschdrumpf]],[[Zumpfal]], [[Fruchtwuazn]]"}, {"kategorie": "Würstelstandjargon", "text": "spitzer, scharfer Pfefferoni (im Unterschied zum [[Öligen]] [milder, in Öl eingelegter Pfefferoni]), [[Gschbitzda]], [[Schbitzal]], [[Käu]], [[Oaschpfeifal]]"}]'::jsonb, 'an Schbitz haum'),
  ('gruschbaeschbitz', 'Gruschbäschbitz', 'der', '', '', 'Wiener Fleischhauer-Slang', 'Kruspelspitz', '[{"kategorie": "wörtlich, Fleischerjargon", "text": "\"Kruspelspitz\" (Determinativkompositum aus [[Kruspel]]=\"Knorpel\" und [[Spitz]]=\"spitz zulaufendes Teilstück vom Rind\")"}, {"kategorie": "allg.", "text": "\"von einem Kruspel durchzogenes, besonders saftiges Teilstück von der [[Rindsschulter]]\", (Deutschland): ausgelöste Zwischenrippe (eignet sich sehr gut als Schmor- und Siedefleisch)"}, {"kategorie": "scherzhaft für", "text": "männliches Glied, Penis, [[Beidl]], [[Schwanzal]], [[Nuudl]], [[Kanari]], [[Karotte]], [[Salzstangerl]]"}]'::jsonb, 'A schee greifda Gruschbäschbitz is es peafekte Fleisch zum Siadn!'),
  ('gruschbae', 'Gruschbä', 'die', '', '', 'Wiener Fleischhauer-Slang', 'Kruspel', '[{"kategorie": "wörtlich", "text": "\"Kruspel\" (vom mittelhochdeutschen \"kruspel\"=\"weicher Knorpel\")"}, {"kategorie": "Fleischerjargon", "text": "\"weicher Knorpel innerhalb eines Fleischstücks\", \"knuspriger Rand eines Fleischstücks\", Schwarte, [[Schwartl]] (z.B. eines [[Kümmelbratens]])"}]'::jsonb, 'Easchd de Gruschbä mochds Fleisch so richtig gschmackig und softig!'),
